import { makeReadingLayoutStyles, StyleBundle } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function expectTypeError(action: () => void, message: string): void {
  let thrown: unknown;
  try { action(); } catch (error) { thrown = error; }
  assert(thrown instanceof TypeError, message);
}
function verify(bundle: StyleBundle, prefix: string): void {
  const container = `.${prefix}-split{display:flex;flex-direction:row}.${prefix}-split>section{width:50%}`;
  const text = `.${prefix}-text h2{color:#273469;font-size:42px;font-weight:700}.${prefix}-text p{font-size:15px;color:rgba(39,52,105,0.72);font-weight:400;padding-right:96px;margin-top:18px}`;
  equal(bundle.container, container, `${prefix} container CSS`);
  equal(bundle.text, text, `${prefix} text CSS`);
  equal(bundle.combined, container + text, `${prefix} combined CSS`);
  assert(Object.isFrozen(bundle), `${prefix} bundle is frozen`);
}

verify(makeReadingLayoutStyles(), "reading");
verify(makeReadingLayoutStyles("A_9-x"), "A_9-x");
verify(makeReadingLayoutStyles("_"), "_");

const first = makeReadingLayoutStyles("custom");
const second = makeReadingLayoutStyles("custom");
assert(first !== second, "each call allocates a new object");
assert(first.container.includes(".custom-split>section"), "direct-child selector is used");
assert(!first.container.includes(".custom-split section"), "descendant selector is not used");

for (const invalid of ["", "9reading", "-reading", "has space", "dot.name", "éclair", "read/ing", "read\ning"]) {
  expectTypeError(() => { makeReadingLayoutStyles(invalid); }, `invalid prefix ${JSON.stringify(invalid)} is rejected`);
}

